/****************************************************************************
 * Name: mic_test_pcm
 *
 * Description:
 *   Capture N seconds of 16 kHz mono (left-channel) PCM.
 *   Prints: actual sample rate, sample count, integer RMS, peak,
 *   and first 16 raw samples.
 *
 *   Uses the same audio_init() power/APLL/analogue sequence, then
 *   re-programs the AUD_CONFIG rate bits to 16 kHz before enabling
 *   the ADC.
 *
 ****************************************************************************/

static int mic_test_pcm(int seconds)
{
  uint32_t val;
  int n;
  int want;
  int i;
  int64_t energy;
  int32_t peak;
  int32_t rms;
  int bit;

  if (seconds < 1)
    {
      seconds = 1;
    }

  if (seconds > MIC_TEST_MAX_SEC)
    {
      seconds = MIC_TEST_MAX_SEC;
    }

  want = MIC_TEST_RATE * seconds;

  /* 1. Full analogue + APLL init (sets 48 kHz by default) */

  audio_init();

  /* 2. Re-program ADC sample rate to 16 kHz */

  val = aud_getreg(AUD_CONFIG);
  val &= ~AUD_RATE_ADC_MASK;
  val |= AUD_RATE_ADC_16K | AUD_APLL_SEL;
  aud_putreg(val, AUD_CONFIG);

  /* ADC frac divider = manual 0 (same as 48 kHz path, APLL handles it) */

  val = aud_getreg(AUD_EXTEND_CFG);
  val &= ~AUD_ADC_FRAC_MANUAL;
  aud_putreg(val, AUD_EXTEND_CFG);

  /* Re-enable ADC + line-in after rate change */

  val = aud_getreg(AUD_CONFIG);
  val |= AUD_ADC_ENABLE | AUD_LINEIN_ENABLE;
  aud_putreg(val, AUD_CONFIG);

  up_mdelay(50);

  syslog(LOG_INFO,
         "[mic] test: rate=%d Hz, capturing %d samples (%d s) ...\n",
         MIC_TEST_RATE, want, seconds);

  /* 3. Poll-capture into static buffer (left channel mono) */

  n = 0;

  while (n < want)
    {
      uint32_t status = aud_getreg(AUD_ADC_CONFIG_1);

      if (!(status & 0x3f))
        {
          continue;
        }

      uint32_t sample = aud_getreg(AUD_ADC_FIFO_PORT);

      g_mic_test_pcm[n] = (int16_t)(sample & 0xffff);
      n++;
    }

  /* 4. Compute integer RMS and peak (left channel = mono) */

  energy = 0;
  peak = 0;

  for (i = 0; i < n; i++)
    {
      int32_t s = g_mic_test_pcm[i];

      energy += (int64_t)s * s;

      if (s < 0)
        {
          s = -s;
        }

      if (s > peak)
        {
          peak = s;
        }
    }

  /* Integer square root for RMS */

  rms = 0;

  if (n > 0)
    {
      int32_t mean = (int32_t)(energy / n);

      for (bit = 15; bit >= 0; bit--)
        {
          int32_t t = rms + (1 << bit);

          if (t * t <= mean)
            {
              rms = t;
            }
        }
    }

  /* 5. Print results */

  syslog(LOG_INFO,
         "[mic] test result:\n"
         "  sample_rate = %d Hz\n"
         "  samples     = %d\n"
         "  duration    = %d ms\n"
         "  RMS         = %d\n"
         "  peak        = %d\n",
         MIC_TEST_RATE, n, (n * 1000) / MIC_TEST_RATE,
         rms, peak);

  syslog(LOG_INFO, "[mic] first 16 samples:\n");

  for (i = 0; i < 16 && i < n; i++)
    {
      syslog(LOG_INFO, "  [%2d] %6d\n", i, g_mic_test_pcm[i]);
    }

  /* 6. Power down */

  audio_deinit();

  return n;
}

